function notionText(runs) {
  if (!Array.isArray(runs)) return "";
  return runs.map((part) => part?.plain_text ?? part?.text?.content ?? "").join("");
}

function notionPage(page) {
  const pageId = page?.pageId ?? page?.id;
  const createdTime = page?.createdTime ?? page?.created_time;
  if (
    typeof pageId !== "string" ||
    !/^[\da-f]{8}(?:-[\da-f]{4}){3}-[\da-f]{12}$/i.test(pageId) ||
    typeof createdTime !== "string" ||
    !Number.isFinite(Date.parse(createdTime))
  ) {
    throw new Error("Notion returned a page without a valid ID and creation time");
  }
  const properties = Object.values(page.properties ?? {});
  const title =
    properties.find((property) => property?.type === "title")?.title ??
    page.properties?.Name?.title;
  return {
    pageId: pageId.toLowerCase(),
    createdTime,
    pageTitle: notionText(title).trim() || "Untitled",
  };
}

function ignoreNotionChildren(type) {
  return ["image", "video", "child_page", "child_database", "link_to_page"].includes(type);
}

function notionBlockText(block) {
  if (["image", "video", "link_to_page"].includes(block.type)) return "";
  if (typeof block.content === "string") return block.content;
  const details = block[block.type] ?? {};
  if (block.type === "table_row") return (details.cells ?? []).map(notionText).join("\t").trim();
  if (block.type === "equation") return details.expression ?? "";
  if (block.type === "child_page" || block.type === "child_database") return details.title ?? "";
  return notionText(details.rich_text ?? details.text);
}

function readFlattenedNotionDocument(source, blocks) {
  const blockedParents = new Set();
  const content = [];
  for (const block of blocks) {
    if (!block?.id || !block?.type)
      throw new Error("Notion returned a block without an ID or type");
    const parent = block.parent?.block_id ?? block.parent_id;
    if (blockedParents.has(parent)) {
      blockedParents.add(block.id);
      continue;
    }
    if (ignoreNotionChildren(block.type)) blockedParents.add(block.id);
    const text = notionBlockText(block);
    if (text.trim()) content.push(text);
  }
  return { ...source, text: content.join("\n") };
}

function pineconeNamespace(namespace) {
  if (typeof namespace !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(namespace)) {
    throw new Error("Enter a Pinecone namespace for these Gemini embeddings");
  }
  return namespace;
}

const indexName = "notion-pages";
const namespace = pineconeNamespace("notion-gemini-embedding-2");
if (!/^[a-z0-9](?:[a-z0-9-]{0,43}[a-z0-9])?$/.test(indexName))
  throw new Error("Configure the Pinecone index name");
const grouped = new Map(
  $("Watch for new Notion pages")
    .all()
    .map((entry) => {
      const page = notionPage(entry.json);
      return [page.pageId, { page, blocks: [] }];
    }),
);
for (const { json: block } of $input.all()) {
  const page = grouped.get(block.root_id?.toLowerCase());
  if (!page) throw new Error("Notion returned a block without a known source page");
  page.blocks.push(block);
}
const documents = [...grouped.values()]
  .map(({ page, blocks }) => readFlattenedNotionDocument(page, blocks))
  .filter((doc) => doc.text.trim());
return documents.length ? [{ json: { documents, indexName, namespace } }] : [];

function splitNotionDocuments(documents, vocabulary) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const byteValues = Object.fromEntries(
    Array.from(alphabet, (character, index) => [character, index]),
  );
  function decodeBase64(encoded) {
    let decoded = "";
    for (let offset = 0; offset < encoded.length; offset += 4) {
      const first = byteValues[encoded[offset]];
      const second = byteValues[encoded[offset + 1]];
      const third = byteValues[encoded[offset + 2]];
      const fourth = byteValues[encoded[offset + 3]];
      decoded += String.fromCharCode((first << 2) | (second >> 4));
      if (third !== undefined) decoded += String.fromCharCode(((second & 15) << 4) | (third >> 2));
      if (fourth !== undefined) decoded += String.fromCharCode(((third & 3) << 6) | fourth);
    }
    return decoded;
  }
  const ranks = new Map();
  const tokens = [];
  for (const line of vocabulary.trimEnd().split("\n")) {
    const separator = line.indexOf(" ");
    const bytes = decodeBase64(line.slice(0, separator));
    const rank = Number(line.slice(separator + 1));
    if (!bytes || rank !== tokens.length) throw new Error("Unexpected cl100k_base vocabulary");
    ranks.set(bytes, rank);
    tokens.push(bytes);
  }
  if (tokens.length !== 100256) throw new Error("Unexpected cl100k_base vocabulary size");
  const special = [
    "<|endoftext|>",
    "<|fim_prefix|>",
    "<|fim_middle|>",
    "<|fim_suffix|>",
    "<|endofprompt|>",
  ];
  const specialPattern = /(<\|(?:endoftext|fim_prefix|fim_middle|fim_suffix|endofprompt)\|>)/g;
  const piecePattern =
    /('s|'S|'t|'T|'re|'rE|'Re|'RE|'ve|'vE|'Ve|'VE|'m|'M|'ll|'lL|'Ll|'LL|'d|'D)|[^\r\n\p{L}\p{N}]?\p{L}+|\p{N}{1,3}| ?[^\s\p{L}\p{N}]+[\r\n]*|\s*[\r\n]+|\s+(?!\S)|\s+/gu;
  const encoder = new TextEncoder();
  const decoder = new TextDecoder();
  const cache = new Map();
  function byteString(bytes) {
    let value = "";
    for (let offset = 0; offset < bytes.length; offset += 2048) {
      value += String.fromCharCode(...bytes.subarray(offset, offset + 2048));
    }
    return value;
  }
  function encodePiece(piece) {
    const cached = cache.get(piece);
    if (cached) return cached;
    const bytes = /^[\x00-\x7f]+$/.test(piece) ? piece : byteString(encoder.encode(piece));
    const direct = ranks.get(bytes);
    if (direct !== undefined) return [bytes];
    const parts = bytes.split("");
    const adjacentRanks = parts
      .slice(1)
      .map((part, index) => ranks.get(parts[index] + part) ?? Infinity);
    while (adjacentRanks.length) {
      let best = Infinity;
      let index = -1;
      for (let candidate = 0; candidate < adjacentRanks.length; candidate++) {
        if (adjacentRanks[candidate] < best) {
          best = adjacentRanks[candidate];
          index = candidate;
        }
      }
      if (index < 0) break;
      parts.splice(index, 2, parts[index] + parts[index + 1]);
      adjacentRanks.splice(index, 1);
      if (index > 0)
        adjacentRanks[index - 1] = ranks.get(parts[index - 1] + parts[index]) ?? Infinity;
      if (index + 1 < parts.length)
        adjacentRanks[index] = ranks.get(parts[index] + parts[index + 1]) ?? Infinity;
    }
    cache.set(piece, parts);
    return parts;
  }
  const chunks = [];
  for (const { text, ...page } of documents) {
    const encoded = [];
    for (const segment of text.split(specialPattern)) {
      if (special.includes(segment)) {
        encoded.push(segment);
        continue;
      }
      for (const piece of segment.matchAll(piecePattern)) {
        for (const bytes of encodePiece(piece[0])) encoded.push(bytes);
      }
    }
    for (let start = 0, chunkIndex = 0; start < encoded.length; start += 226, chunkIndex++) {
      const end = Math.min(start + 256, encoded.length);
      const bytes = encoded.slice(start, end).join("");
      const chunk = decoder.decode(Uint8Array.from(bytes, (value) => value.charCodeAt(0)));
      if (chunk.trim())
        chunks.push({
          id: page.pageId + ":" + String(chunkIndex).padStart(5, "0"),
          metadata: { ...page, text: chunk, chunkIndex },
        });
      if (end === encoded.length) break;
    }
  }
  if (chunks.length > 64) throw new Error("This group of pages exceeds the 64-chunk upsert limit");
  return chunks;
}

function embeddingText(metadata) {
  return "title: " + metadata.pageTitle + " | text: " + metadata.text;
}

const { vocabulary, vocabularyHash } = $input.first().json;
if (vocabularyHash !== "223921b76ee99bde995b7ff738513eef100fb51d18c93597a113bcffe865b2a7")
  throw new Error("Unexpected tokenizer vocabulary checksum");
const config = $("Collect each page separately").first().json;
const chunks = splitNotionDocuments(config.documents, vocabulary);
const requests = chunks.map((chunk) => ({
  model: "models/gemini-embedding-2",
  content: { parts: [{ text: embeddingText(chunk.metadata) }] },
  output_dimensionality: 768,
}));
return [{ json: { chunks, requests, indexName: config.indexName, namespace: config.namespace } }];

function checkEmbedding(vector, reportedLength = vector?.length) {
  if (
    reportedLength !== 768 ||
    !Array.isArray(vector) ||
    vector.length !== 768 ||
    !vector.every(Number.isFinite) ||
    !vector.some((value) => value !== 0)
  ) {
    throw new Error("Gemini did not return a valid 768-dimensional embedding");
  }
  return vector;
}

const plan = $("Split pages and embed chunks").first().json;
const { embeddings } = $input.first().json;
if (!Array.isArray(embeddings) || embeddings.length !== plan.chunks.length)
  throw new Error("Gemini returned the wrong number of embeddings");
const vectors = plan.chunks.map((chunk, position) => ({
  ...chunk,
  values: checkEmbedding(embeddings[position]?.values),
}));
return [{ json: { indexName: plan.indexName, namespace: plan.namespace, vectors } }];

function pineconeIndex(index) {
  const match = /^(?:https:\/\/)?([a-z0-9-]+(?:\.[a-z0-9-]+)*\.pinecone\.io)\/?$/i.exec(
    index?.host ?? "",
  );
  if (
    index?.dimension !== 768 ||
    index.metric !== "cosine" ||
    (index.vector_type != null && index.vector_type !== "dense") ||
    !match ||
    index.status?.ready !== true
  ) {
    throw new Error("Configure a ready 768-dimensional dense cosine Pinecone index");
  }
  return "https://" + match[1];
}

const { vectors, namespace } = $("Check every embedding dimension").first().json;
const host = pineconeIndex($input.first().json);
return [{ json: { host, vectors, namespace } }];

const result = $input.first().json.upsertedCount;
const { vectors } = $("Verify the Pinecone index").first().json;
if (result !== vectors.length) throw new Error("Pinecone did not confirm every vector");
return [{ json: { upserted: result } }];
